import prettier from "eslint-config-prettier";
import svelte from "eslint-plugin-svelte";
import svelteParser from "svelte-eslint-parser";
import globals from "globals";
import ts from "typescript-eslint";
import tsdoc from "eslint-plugin-tsdoc";
import { defineConfig } from "eslint/config";

/**
 * Files are imported via the subpath imports from package.json, see wiki/Contributing.md#imports.
 * `./$types` is generated by SvelteKit next to each route and can't be imported otherwise.
 */
const relativeImports = {
    // Catches ".", "..", "./foo" and "../foo", including "../$types"; only exactly "./$types" is allowed.
    regex: "^(?!\\./\\$types$)\\.\\.?(/|$)",
    message:
        "Use the subpath imports #lib/, #routes/ or #tests/ instead of relative imports, see wiki/Contributing.md#imports.",
};

/** SvelteKit 3 no longer resolves `$lib`; catching it here gives a clearer hint than the build error. */
const removedAliases = {
    regex: "^\\$(lib|tests)(/|$)",
    message:
        "The $lib and $tests aliases were replaced by the subpath imports #lib/ and #tests/ with explicit extensions, e.g. #lib/foo.js, see wiki/Contributing.md#imports.",
};

const testOnlyImports = {
    regex: "^#(routes|tests)/",
    message: "#routes/ and #tests/ are only imported in tests/, see wiki/Contributing.md#imports.",
};

/** Backend access goes through the domain modules in src/lib/api/, see wiki/Contributing.md#backend-access. */
const apiInternals = [
    {
        group: ["snowballr-api", "snowballr-api/**"],
        message:
            "Generated API code is only used inside src/lib/api/. Import its types from #lib/api/types.js and call the domain functions in #lib/api/ instead.",
    },
    {
        group: ["@protobuf-ts/**"],
        message:
            "The protobuf-ts runtime is only used inside src/lib/api/. Call the domain functions in #lib/api/ and check errors with isApiError from #lib/api/errors.js instead.",
    },
    {
        // The leading **/ catches every path to these modules; the trailing * catches the extension.
        group: ["**/api/client*", "**/api/grpc*", "**/api/fieldmask*"],
        message:
            "The client, call() and FieldMasks are internal to src/lib/api/. Call the domain functions in #lib/api/ instead.",
    },
];

/**
 * `no-restricted-imports` of a later config block replaces the one of an earlier block instead of merging with it,
 * so each block lists all patterns that apply to its files. The removed aliases are rejected everywhere.
 */
function restrictImports(...patterns) {
    return { "no-restricted-imports": ["error", { patterns: [removedAliases, ...patterns] }] };
}

export default defineConfig(
    ...ts.configs.recommended,
    ...svelte.configs["flat/recommended"],
    prettier,
    ...svelte.configs["flat/prettier"],
    {
        languageOptions: {
            globals: {
                ...globals.browser,
                ...globals.node,
            },
        },
    },
    {
        files: ["**/*.svelte", "*.svelte"],
        languageOptions: {
            parser: svelteParser,
            parserOptions: {
                parser: ts.parser,
            },
        },
        plugins: {
            tsdoc,
        },
        rules: {
            "tsdoc/syntax": "warn",
        },
    },
    {
        files: ["**/*.svelte.ts", "*.svelte.ts"],
        languageOptions: {
            parser: svelteParser,
            parserOptions: {
                parser: ts.parser,
            },
        },
        plugins: {
            tsdoc,
        },
        rules: {
            "tsdoc/syntax": "warn",
        },
    },
    {
        files: ["**/*.ts", "*.ts"],
        languageOptions: {
            parser: ts.parser,
        },
        plugins: {
            tsdoc,
        },
        rules: {
            "tsdoc/syntax": "warn",
        },
    },
    {
        ignores: [
            "build/",
            ".svelte-kit/",
            "dist/",
            "coverage/",
            "e2e-report/",
            "visual-report/",
            "node_modules/",
        ],
    },
    {
        rules: {
            "svelte/button-has-type": "error",
            "svelte/prefer-const": "error",
            "svelte/html-closing-bracket-new-line": "error",
            "svelte/prefer-class-directive": "warn",
            "svelte/spaced-html-comment": "warn",
            "svelte/prefer-destructured-store-props": "error",
            "svelte/prefer-style-directive": "warn",
            "svelte/shorthand-attribute": "warn",
            "svelte/shorthand-directive": "warn",
            "svelte/html-quotes": "error",
            "svelte/sort-attributes": "error",
            "svelte/no-ignored-unsubscribe": "error",
            "svelte/no-navigation-without-resolve": "off",
        },
    },
    {
        files: ["**/*.js", "**/*.ts", "**/*.svelte"],
        rules: restrictImports(relativeImports),
    },
    {
        files: ["src/**/*.js", "src/**/*.ts", "src/**/*.svelte"],
        rules: restrictImports(relativeImports, testOnlyImports, ...apiInternals),
    },
    {
        files: ["src/lib/api/**"],
        rules: restrictImports(relativeImports, testOnlyImports),
    },
    {
        // shadcn/ui components are kept as the shadcn-svelte CLI generates them, i.e. with relative imports.
        files: ["src/lib/components/primitives/**"],
        rules: restrictImports(testOnlyImports, ...apiInternals),
    },
);
